steps.script:
SettingsService.set("auto_allocate_wounds", true)
for uid in GameState.state.units:
	var u = GameState.state.units[uid]
	if int(u.get("owner", 0)) == 2:
		for m in u.models:
			m["wounds"] = 99
			m["current_wounds"] = 99
return true

var out = "absent"
for n in tree.root.get_children():
	var s = n.get_script()
	if s == null or not str(s.resource_path).ends_with("EpicChallengeDialog.gd"):
		continue
	var q = [n]
	while not q.is_empty():
		var c = q.pop_front()
		if c is Button and str(c.text) == "Decline":
			c.pressed.emit()
			out = "declined"
			break
		for ch in c.get_children():
			q.append(ch)
return out

var u = GameState.get_unit("U_WARBOSS_A")
var t = GameState.get_unit("U_SHIELD_CAPTAIN_A")
var m = RulesEngine.ork11e_ab_mods(u, t, {"name": "Power klaw", "type": "Melee"}, true, GameState.state, [])
print("[wp-o6] mods ", "U_WARBOSS_A", " -> ", "U_SHIELD_CAPTAIN_A", ": ", m)
return int(m.attacks) == 3 and int(m.strength) == 2

var p = PhaseManager.get_current_phase_instance()
var rows := []
for d in p.dice_log:
	if typeof(d) == TYPE_DICTIONARY and str(d.get("context", "")) == "hit_roll_melee":
		rows.append([str(d.get("weapon", d.get("weapon_name", ""))), d.get("total_attacks", d.get("rolls_raw", []).size())])
print("[wp-o6] Warboss melee rows: ", rows)
if rows.is_empty():
	return false
for r in rows:
	if int(r[1]) < 9:
		return false
return true
